php:data-api.template:
// Data API: find records where {{php:field}} matches {{php:value}}
$result = $bridge->findRecords([
    'query' => [[
        '{{php:field}}' => '{{php:value}}',
    ]],
    'limit' => {{integer:limit}},
]);

javascript:data-api.template:
// Browser-safe read: ask the protected PHP bridge to run a Data API find.
const response = await fetch('/openbridge-api.php', {
  method: 'POST',
  credentials: 'include',
  headers: {
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({
    action: 'playground',
    transport: 'data-api',
    operation: 'find',
    resource: {{js:resource}},
    limit: {{integer:limit}},
    query: [
      {
        [{{js:field}}]: {{js:value}},
      },
    ],
  }),
});

const result = await response.json();

javascript:odata.template:
// Browser-safe read: ask the protected PHP bridge to run an OData filter.
const response = await fetch('/openbridge-api.php', {
  method: 'POST',
  credentials: 'include',
  headers: {
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({
    action: 'playground',
    transport: 'odata',
    operation: 'find',
    resource: {{js:resource}},
    table: {{js:resource}},
    limit: {{integer:limit}},
    filter: String({{odataFieldJs:field}}) + " eq '" + {{odataJs:value}} + "'",
  }),
});

const result = await response.json();
